@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ schema1:additionalType "no value available: unnamed property" ;
                    schema1:hasPart [ schema1:additionalType "no value available: unnamed property" ;
                            schema1:name "no value available: unnamed property" ] ] ;
            sh:resultMessage "An instrument must have a name with at least 3 characters." ;
            sh:resultPath schema1:name ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "An instrument must have a name with at least 3 characters." ;
                    sh:minCount 1 ;
                    sh:minLength 3 ;
                    sh:path schema1:name ;
                    sh:severity sh:Violation ] ] .

